<template>
  <section class="sales-workspace" aria-label="模块商品销售工作区">
    <header class="sales-heading"><div><span class="eyebrow">SALES & RENEWAL</span><h3>选模块，核对合同，再创建订单</h3><p>新购与续费都新增订单来源；本工作区不收款、不自动切换旧客户授权、不恢复已销毁数据。</p></div><span class="badge">真实商品 · 未支付录单</span></header>
    <div class="school-tools">
      <label>检索学校<input v-model.trim="schoolKeyword" maxlength="100" placeholder="学校名称或编码" @keyup.enter="loadSchools(1)"></label>
      <button type="button" :disabled="schoolsLoading" @click="loadSchools(1)">查询</button>
      <label class="school-select">办理学校<select :value="tenantId" :disabled="locked || sending || !!attempt" @change="chooseSchool"><option value="">请选择学校</option><option v-if="tenantId && !schools.some(s => s.tenantId === tenantId)" :value="tenantId">{{ context?.tenantName || '当前已选学校' }} · {{ tenantId }}</option><option v-for="school in schools" :key="school.tenantId" :value="school.tenantId">{{ school.tenantName }} · {{ school.tenantCode }}</option></select></label>
      <div class="pager"><button :disabled="schoolsLoading || schoolPage === 1" @click="loadSchools(schoolPage - 1)">上一页</button><span>{{ schoolPage }} / {{ Math.max(1, Math.ceil(schoolTotal / 30)) }}</span><button :disabled="schoolsLoading || schoolPage * 30 >= schoolTotal" @click="loadSchools(schoolPage + 1)">下一页</button></div>
    </div>
    <p v-if="schoolError" class="error" role="alert">{{ schoolError }}</p>
    <p v-if="contextLoading" class="notice" role="status">正在核对学校代次与已付服务期，核对完成前不能下单。</p>
    <p v-else-if="context?.readerVersion === 'LEGACY'" class="notice">该校仍使用旧商业读取方式。分项订单不会自动覆盖原套餐；已有正式合同的学校还需完成影子对账与受控迁移。</p>
    <div class="tabs" role="tablist" aria-label="商业办理步骤"><button v-for="item in tabs" :id="`sales-tab-${item.key}`" :key="item.key" role="tab" :aria-selected="tab === item.key" :aria-controls="`sales-panel-${item.key}`" @click="selectTab(item.key)">{{ item.label }}</button></div>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="success" role="status">{{ notice }}</p>
    <section v-show="tab === 'order'" id="sales-panel-order" role="tabpanel" aria-labelledby="sales-tab-order">
      <div v-if="attempt" class="pending"><strong>上次请求的结果仍需核对</strong><p>请保留原请求重试。系统复用同一幂等键，不另建第二张单；草稿和学校已暂时锁定。</p><button :disabled="sending || !canOrder" @click="submitOrder">{{ sending ? '正在核对原请求…' : '核对原请求结果' }}</button></div>
      <div v-if="receipt" class="success"><strong>订单 {{ receipt.orderNo }} 已创建或找回</strong><p>创建回执不代表已收款或开通。实际支付与履约状态以订单台账为准。</p><button @click="selectTab('ledger')">查看该校分项台账</button> <router-link :to="{ path:'/admin/platform/orders', query:{ tenantId, orderNo:receipt.orderNo } }">到原订单中心核对收款</router-link></div>
      <fieldset :disabled="!canOrder || sending || !!attempt || locked || contextLoading || !context">
        <div class="draft-head"><label>业务类型<select v-model="orderType" @change="invalidateQuote"><option value="NEW">新购 / 增购模块</option><option value="RENEW">续费（延续当前代次）</option></select></label><label class="grow">合同 / 报价说明<input v-model.trim="remark" minlength="5" maxlength="500" placeholder="填写可追溯的合同编号和成交说明，至少5字符" @input="invalidateQuote"></label></div>
        <div class="catalog-tools"><label>可售模块<select v-model="catalogModule" @change="loadCatalog(1)"><option value="">全部核心模块</option><option v-for="mod in modules" :key="mod.moduleKey" :value="mod.moduleKey">{{ mod.label }}</option></select></label><label class="grow">检索商品<input v-model.trim="catalogKeyword" maxlength="100" placeholder="商品名称或SKU编码" @keyup.enter="loadCatalog(1)"></label><button type="button" @click="loadCatalog(1)">查询商品</button></div>
        <p v-if="catalogLoading" role="status">正在读取已发布商品…</p><p v-else-if="catalogError" class="error" role="alert">{{ catalogError }}</p><p v-else-if="!skus.length" class="empty">没有符合条件的已发布商品。请先在“商品版本”发布真实价格与政策，不会自动生成套餐价格。</p>
        <div class="catalog-grid"><button v-for="sku in skus" :key="`${sku.skuCode}:${sku.revision}`" type="button" class="sku" :disabled="rows.some(r => r.moduleKey === sku.moduleKey)" @click="addSku(sku)"><span>{{ moduleLabel(sku.moduleKey) }}</span><strong>{{ sku.name }}</strong><small>{{ sku.skuCode }} · 第 {{ sku.revision }} 版</small><b>{{ sku.pricePolicy.currency }} {{ sku.pricePolicy.unitPrice }}</b><small>按本商品版本的计价单位；合同服务期另行填写</small><small>{{ rows.some(r => r.moduleKey === sku.moduleKey) ? '该模块已选，可移除后换版本' : '加入分项' }}</small></button></div>
        <div class="pager"><button type="button" :disabled="catalogLoading || catalogPage === 1" @click="loadCatalog(catalogPage - 1)">上一页商品</button><span>共 {{ catalogTotal }} 个已发布版本</span><button type="button" :disabled="catalogLoading || catalogPage * 30 >= catalogTotal" @click="loadCatalog(catalogPage + 1)">下一页商品</button></div>
        <article v-for="(row,index) in rows" :key="row.moduleKey" class="order-line"><header><h4>{{ index + 1 }} · {{ moduleLabel(row.moduleKey) }} <small>{{ row.skuCode }} / 第{{ row.skuRevision }}版</small></h4><button type="button" @click="removeLine(index)">移除此项</button></header><p v-if="context?.paidThrough?.[row.moduleKey]" class="coverage">已有已付截止（北京时间）：{{ showTime(context.paidThrough[row.moduleKey]) }} <button v-if="orderType === 'RENEW'" type="button" @click="useRenewalBoundary(row)">从该截止续费</button></p><div class="line-fields" @input="invalidateQuote"><label>成交单价<input v-model="row.unitPrice" inputmode="decimal"></label><label>数量<input v-model.number="row.quantity" type="number" min="1" max="1000000"></label><label>优惠金额<input v-model="row.discountAmount" inputmode="decimal"></label><div class="line-net"><span>分项净额 {{ row.currency }}</span><strong>{{ displayNet(row) }}</strong></div><label>服务开始（北京时间）<input v-model="row.startLocal" type="datetime-local" step="1"></label><label>服务截止（北京时间，不含）<input v-model="row.endLocal" type="datetime-local" step="1"></label></div></article>
        <div class="submit-bar"><span>{{ rows.length }} 个模块；不会自动赠送就业或 API 能力</span><button type="button" class="primary" :disabled="previewing || !rows.length" @click="previewOrder">{{ previewing ? '后端正在预检…' : '核算金额与服务期' }}</button></div>
      </fieldset>
      <p v-if="!canOrder" class="notice">当前身份没有 order.manage 职责，只能查看；操作权限始终由后端复核。</p>
      <div v-if="quote" class="quote"><h4>提交前核对 · {{ quote.tenantName }}</h4><strong class="quote-total">{{ quote.currency }} {{ quote.totalAmount }}</strong><p>共 {{ quote.items.length }} 个分项，代次由服务端读取。预检不预留授权或额度，正式提交时再核验。</p><p v-for="warning in quote.warnings" :key="warning.moduleKey" class="notice">{{ moduleLabel(warning.moduleKey) }}：{{ warning.message }} 截止 {{ showTime(warning.paidThrough) }}</p><label class="check"><input v-model="confirmed" type="checkbox" :disabled="sending">我已核对学校、各分项价格及起止时间，确认仅创建未支付订单。</label><button class="primary" :disabled="!confirmed || sending || locked || !canOrder" @click="submitOrder">{{ sending ? '正在提交，请勿重复操作…' : '创建未支付订单' }}</button></div>
    </section>
    <section v-show="tab === 'catalog'" id="sales-panel-catalog" role="tabpanel" aria-labelledby="sales-tab-catalog">
      <h4>发布不可变商品版本</h4><p>已发布版本不能覆盖修改。调价请增加版本号，已有订单仍保留签约时的价格、功能和额度快照。</p>
      <form @submit.prevent="publishProduct"><fieldset :disabled="!canPublish || publishing"><div class="publish-grid"><label>模块<select v-model="product.moduleKey" @change="resetProductFeatures"><option v-for="mod in modules" :key="mod.moduleKey" :value="mod.moduleKey">{{ mod.label }}</option></select></label><label>商品名称<input v-model.trim="product.name" required maxlength="100"></label><label>SKU编码<input v-model.trim="product.skuCode" required pattern="[A-Za-z0-9][A-Za-z0-9_.-]{0,63}" placeholder="如 YK-INTERNSHIP"></label><label>版本号<input v-model.number="product.revision" type="number" min="1" max="2147483647" required></label><label>目录单价（CNY）<input v-model="product.unitPrice" inputmode="decimal" required placeholder="请填写真实定价"></label><label>学生额度（留空不配置）<input v-model="product.students" type="number" min="0" max="2147483647"></label><label>存储额度 GiB（留空不配置）<input v-model="product.storageGiB" type="number" min="0" max="1000000"></label><label>生命周期政策版本<input v-model.trim="product.lifecyclePolicyVersion" required maxlength="64" placeholder="填写已确定的政策版本"></label></div><fieldset class="features"><legend>本版本明确包含的功能（仅服务器批准范围）</legend><label v-for="feature in approvedFeatures" :key="feature"><input v-model="product.features" type="checkbox" :value="feature" :disabled="feature === coreFeature(product.moduleKey)">{{ featureLabel(feature) }}</label></fieldset><label>发布原因<input v-model.trim="product.reason" required minlength="5" maxlength="500" placeholder="说明商品版本和定价依据，至少5字符"></label><p class="notice">本表不设置法定保留天数、不计算税额，也不替代合同审批；税务口径保持待确认。</p><button class="primary" :disabled="publishing || !approvedFeatures.length">{{ publishing ? '正在发布…' : '发布商品版本（不授权学校）' }}</button></fieldset></form><p v-if="!canPublish" class="notice">当前身份没有 commercial.manage 职责，不能发布商品。</p>
    </section>
    <section v-show="tab === 'ledger'" id="sales-panel-ledger" role="tabpanel" aria-labelledby="sales-tab-ledger">
      <div class="ledger-tools"><h4>当前学校 · 分项订单台账</h4><label>支付状态<select v-model="orderStatus" @change="loadOrders(1)"><option value="">全部</option><option value="unpaid">未支付</option><option value="paid">已支付</option><option value="cancelled">已取消</option></select></label><button :disabled="ordersLoading || !tenantId" @click="loadOrders(orderPage)">刷新台账</button></div><p v-if="ordersLoading" role="status">正在读取真实订单…</p><div class="table-scroll"><table><thead><tr><th>订单号 / 时间</th><th>类型</th><th>分项</th><th>总额</th><th>已付金额</th><th>支付状态</th><th>操作</th></tr></thead><tbody><tr v-for="order in orders" :key="order.orderId"><td>{{ order.orderNo }}<small>{{ showTime(order.createdAt) }}</small></td><td>{{ order.orderType === 'RENEW' ? '续费' : order.orderType === 'NEW' ? '新购' : order.orderType }}</td><td>{{ order.itemCount }}</td><td>{{ order.currency }} {{ order.totalAmount }}</td><td>{{ order.currency }} {{ order.paidAmount }}</td><td>{{ statusLabel(order.status) }}</td><td><button :disabled="detailLoading" @click="openOrder(order)">查看冻结分项</button></td></tr><tr v-if="!orders.length && !ordersLoading"><td colspan="7">{{ tenantId ? '此条件下暂无分项订单，不代表没有旧套餐合同' : '请先选择学校' }}</td></tr></tbody></table></div><div class="pager"><button :disabled="ordersLoading || orderPage === 1" @click="loadOrders(orderPage - 1)">上一页订单</button><span>共 {{ orderTotal }} 张 · 第 {{ orderPage }} 页</span><button :disabled="ordersLoading || orderPage * 20 >= orderTotal" @click="loadOrders(orderPage + 1)">下一页订单</button></div>
      <div class="export-bar"><label class="grow">导出原因<input v-model.trim="exportReason" minlength="5" maxlength="500" placeholder="如核对本月模块合同分项台账"></label><button :disabled="exporting || !tenantId || !canOrder" @click="exportLedger">{{ exporting ? '审计并生成中…' : '导出此条件的 xlsx' }}</button><small>按学校与支付状态导出，最多1000分项；超限会拒绝，不悄悄截断。</small></div>
      <div v-if="detail" class="detail"><h4>{{ detail.orderNo }} · 签约快照</h4><p>订单状态：{{ statusLabel(detail.status) }}。已支付不等于所有模块已履约，请核对每一行。</p><div class="table-scroll"><table><thead><tr><th>模块 / 商品版本</th><th>代次</th><th>数量 × 单价 − 优惠</th><th>净额 / 币种</th><th>服务期（北京时间）</th><th>履约状态</th></tr></thead><tbody><tr v-for="line in detail.items" :key="line.lineNo"><td>{{ moduleLabel(line.moduleKey) }}<small>{{ line.skuCode }} / {{ line.skuRevision }}</small></td><td>{{ line.generation }}</td><td>{{ line.quantity }} × {{ line.unitPrice }} − {{ line.discountAmount }}</td><td>{{ line.netAmount }} {{ line.currency }}</td><td>{{ showTime(line.startAt) }}<br>至 {{ showTime(line.endAt) }}（不含）</td><td>{{ line.fulfillmentStatus }}</td></tr></tbody></table></div><p>金额和功能来自订单冻结分项，不随后来商品调价而改变。</p></div>
    </section>
  </section>
</template>
<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { moduleCommerceApi as api } from '@/modules/platform/api/moduleCommerce.api'
import { ensurePlatformAccessContext } from '@/security/platformAccessGate'
import { downloadXlsxFromApi } from '@/utils/xlsxDownload'
import { lineAmount, localInputToUtc, utcToLocalInput, renewalInputFromUtc, moneyCents, newOrderAttempt, restoreOrderAttempt, isDefinitiveRejection } from '../../lib/moduleCommerceSales.mjs'
const props = defineProps({ tenantId: { type:String, default:'' }, locked:Boolean })
const emit = defineEmits(['update:tenantId', 'order-created'])
const tabs = [{ key:'order', label:'分项订购与续费' }, { key:'catalog', label:'商品版本' }, { key:'ledger', label:'分项订单台账' }]
const tab=ref('order'), access=ref(null), context=ref(null), error=ref(''), notice=ref('')
const schools=ref([]), schoolKeyword=ref(''), schoolPage=ref(1), schoolTotal=ref(0), schoolsLoading=ref(false), schoolError=ref('')
const skus=ref([]), modules=ref([]), catalogModule=ref(''), catalogKeyword=ref(''), catalogPage=ref(1), catalogTotal=ref(0), catalogLoading=ref(false), catalogError=ref('')
const contextLoading=ref(false), rows=ref([]), orderType=ref('NEW'), remark=ref(''), quote=ref(null), confirmed=ref(false), receipt=ref(null), attempt=ref(null), previewing=ref(false), sending=ref(false)
const orders=ref([]), orderTotal=ref(0), orderPage=ref(1), orderStatus=ref(''), ordersLoading=ref(false), detail=ref(null), detailLoading=ref(false), exportReason=ref(''), exporting=ref(false), publishing=ref(false)
const product=ref({moduleKey:'internship',name:'',skuCode:'',revision:1,unitPrice:'',students:'',storageGiB:'',lifecyclePolicyVersion:'',reason:'',features:['internship']})
let epoch=0, schoolSeq=0, catalogSeq=0, orderSeq=0, detailSeq=0, contextSeq=0, previewSeq=0
const canOrder=computed(()=>!!access.value?.duties?.some(d=>['*','order.manage'].includes(d)))
const canPublish=computed(()=>!!access.value?.duties?.some(d=>['*','commercial.manage'].includes(d)))
const approvedFeatures=computed(()=>modules.value.find(m=>m.moduleKey===product.value.moduleKey)?.approvedFeatures||[])
const coreFeature=k=>k==='graduationDesign'?'graduation':k
const featureLabel=k=>({internship:'岗位实习',graduation:'毕业设计',studentAffairs:'学工',academicAffairs:'教务',studentProfile:'学生主档',fileUpload:'文件上传',studentImport:'学生导入',studentExport:'学生导出',approval:'审批',todoMessage:'待办消息',auditLog:'审计',dataExport:'数据导出',miniapp:'小程序',orientation:'迎新',campusService:'校园服务',riskWarning:'预警'})[k]||k
const moduleLabel=k=>modules.value.find(m=>m.moduleKey===k)?.label||({internship:'岗位实习中心',graduationDesign:'毕业设计中心',studentAffairs:'学工中心',academicAffairs:'教务中心'})[k]||k
const statusLabel=s=>({unpaid:'未支付',paid:'已支付',cancelled:'已取消'})[s]||s
const showTime=v=>v?utcToLocalInput(v).replace('T',' '):'—'
const displayNet=r=>{try{return lineAmount(r.unitPrice,r.quantity,r.discountAmount)}catch{return '待核对'}}
const stamp=()=>JSON.stringify({tenantId:props.tenantId,orderType:orderType.value,remark:remark.value,rows:rows.value})
const storageKey=()=>`gx_module_sales_pending_v1:${access.value?.subjectId||''}:${props.tenantId}`
function invalidateQuote(){quote.value=null;confirmed.value=false;previewSeq++}
function resetProductFeatures(){product.value.features=[coreFeature(product.value.moduleKey)]}
async function loadSchools(page=1){const seq=++schoolSeq;schoolsLoading.value=true;schoolError.value='';try{const data=await api.listSalesTenants({keyword:schoolKeyword.value,page,pageSize:30});if(seq!==schoolSeq)return;schools.value=data.items;schoolTotal.value=data.total;schoolPage.value=page}catch(e){if(seq===schoolSeq){schools.value=[];schoolTotal.value=0;schoolError.value=e.message}}finally{if(seq===schoolSeq)schoolsLoading.value=false}}
async function loadCatalog(page=1){const seq=++catalogSeq;catalogLoading.value=true;catalogError.value='';try{const data=await api.listSaleSkus({moduleKey:catalogModule.value,keyword:catalogKeyword.value,page,pageSize:30});if(seq!==catalogSeq)return;skus.value=data.items;modules.value=data.modules;catalogTotal.value=data.total;catalogPage.value=page}catch(e){if(seq===catalogSeq){skus.value=[];catalogTotal.value=0;catalogError.value=e.message}}finally{if(seq===catalogSeq)catalogLoading.value=false}}
function chooseSchool(event){const next=event.target.value;if(attempt.value||((rows.value.length>0)&&!window.confirm('切换学校将清空未提交的销售草稿，确认继续？'))){event.target.value=props.tenantId;return}emit('update:tenantId',next)}
async function loadContext(){const id=props.tenantId,seq=++contextSeq;context.value=null;contextLoading.value=!!id;if(!id)return;try{const data=await api.getSalesContext(id);if(seq===contextSeq&&id===props.tenantId)context.value=data}catch(e){if(seq===contextSeq)error.value=e.message}finally{if(seq===contextSeq)contextLoading.value=false}}
function loadPending(){attempt.value=null;if(!props.tenantId||!access.value?.subjectId)return;try{attempt.value=restoreOrderAttempt(sessionStorage.getItem(storageKey()),props.tenantId)}catch(e){error.value=e.message;access.value=null}}
watch(()=>props.tenantId,()=>{epoch++;orderSeq++;detailSeq++;ordersLoading.value=false;detailLoading.value=false;invalidateQuote();rows.value=[];remark.value='';orders.value=[];orderTotal.value=0;detail.value=null;receipt.value=null;error.value='';notice.value='';loadPending();loadContext();if(tab.value==='ledger')loadOrders(1)})
function addSku(sku){if(rows.value.some(r=>r.moduleKey===sku.moduleKey))return;rows.value.push({moduleKey:sku.moduleKey,skuCode:sku.skuCode,skuRevision:sku.revision,skuContentHash:sku.contentHash,currency:sku.pricePolicy.currency,quantity:1,unitPrice:sku.pricePolicy.unitPrice,discountAmount:'0.00',startLocal:'',endLocal:''});invalidateQuote()}
function removeLine(index){rows.value.splice(index,1);invalidateQuote()}
function useRenewalBoundary(row){row.startLocal=renewalInputFromUtc(context.value.paidThrough[row.moduleKey]);invalidateQuote()}
async function previewOrder(){error.value='';notice.value='';const startStamp=stamp(),seq=++previewSeq,token=epoch;previewing.value=true;quote.value=null;confirmed.value=false;try{const body={tenantId:props.tenantId,orderType:orderType.value,remark:remark.value,items:rows.value.map(r=>({skuCode:r.skuCode,skuRevision:r.skuRevision,skuContentHash:r.skuContentHash,quantity:r.quantity,unitPrice:r.unitPrice,discountAmount:r.discountAmount,startAt:localInputToUtc(r.startLocal),endAt:localInputToUtc(r.endLocal)}))};const result=await api.previewSalesOrder(body);if(token===epoch&&seq===previewSeq&&startStamp===stamp())quote.value=result}catch(e){if(token===epoch&&seq===previewSeq)error.value=e.message}finally{previewing.value=false}}
async function submitOrder(){if(sending.value||!canOrder.value||(!attempt.value&&(!confirmed.value||!quote.value)))return;sending.value=true;error.value='';const token=epoch;try{const current=await ensurePlatformAccessContext({force:true});if(!current||String(current.subjectId)!==String(access.value?.subjectId)||!current.duties?.some(d=>['*','order.manage'].includes(d)))throw new Error('平台身份或职责已变化，未发送订单；请先恢复原身份并核对台账');if(!attempt.value)attempt.value=newOrderAttempt(quote.value.order);sessionStorage.setItem(storageKey(),JSON.stringify(attempt.value));const result=await api.createSalesOrder(attempt.value.order,attempt.value.key);if(token!==epoch)return;if(!result?.orderNo||result.paymentRecorded!==false||result.rightsMaterialized!==false)throw new Error('未取得明确的未支付创建回执，请核对原请求');sessionStorage.removeItem(storageKey());attempt.value=null;receipt.value=result;rows.value=[];invalidateQuote();emit('order-created',result);await loadOrders(1)}catch(e){if(token!==epoch)return;error.value=e.message||'提交结果不明，请核对原请求';if(isDefinitiveRejection(e)){sessionStorage.removeItem(storageKey());attempt.value=null;invalidateQuote()}}finally{sending.value=false}}
async function selectTab(key){tab.value=key;if(key==='ledger')await loadOrders(1)}
async function loadOrders(page=1){const id=props.tenantId,token=epoch,seq=++orderSeq;detailSeq++;detailLoading.value=false;orders.value=[];detail.value=null;ordersLoading.value=!!id;if(!id)return;try{const data=await api.listSalesOrders({tenantId:id,status:orderStatus.value,page,pageSize:20});if(token!==epoch||seq!==orderSeq)return;orders.value=data.items;orderTotal.value=data.total;orderPage.value=page}catch(e){if(token===epoch&&seq===orderSeq){orderTotal.value=0;error.value=e.message}}finally{if(seq===orderSeq)ordersLoading.value=false}}
async function openOrder(order){const token=epoch,seq=++detailSeq;detail.value=null;detailLoading.value=true;try{const data=await api.getSalesOrder(props.tenantId,order.orderId);if(token===epoch&&seq===detailSeq)detail.value=data}catch(e){if(token===epoch&&seq===detailSeq)error.value=e.message}finally{if(seq===detailSeq)detailLoading.value=false}}
async function exportLedger(){if(exporting.value)return;exporting.value=true;error.value='';const token=epoch;try{const data=await api.exportSalesOrders({tenantId:props.tenantId,status:orderStatus.value,reason:exportReason.value});if(token!==epoch)return;if(!data?.contentBase64||data.truncated!==false)throw new Error('导出未返回完整文件');downloadXlsxFromApi(data);notice.value=`已生成并审计 ${data.rowCount} 条分项`}catch(e){if(token===epoch)error.value=e.message}finally{exporting.value=false}}
async function publishProduct(){if(!canPublish.value||publishing.value)return;publishing.value=true;error.value='';notice.value='';try{moneyCents(product.value.unitPrice);const quotas={};for(const [field,key,unit,factor] of [['students','students','COUNT',1],['storageGiB','storageBytes','BYTES',1024**3]]){const raw=product.value[field];if(raw!==''){if(!/^\d+$/.test(String(raw))||!Number.isSafeInteger(Number(raw)*factor))throw new Error('额度须为安全范围内的非负整数');quotas[key]={limit:Number(raw)*factor,unit,aggregation:'MAX'}}}const sku={skuCode:product.value.skuCode,revision:product.value.revision,name:product.value.name,productType:'MODULE',moduleKey:product.value.moduleKey,features:Object.fromEntries(product.value.features.map(f=>[f,true])),quotas,pricePolicy:{unitPrice:product.value.unitPrice,currency:'CNY',taxTreatment:'UNSPECIFIED'},lifecyclePolicyVersion:product.value.lifecyclePolicyVersion};const result=await api.publishSku({sku,reason:product.value.reason});notice.value=`商品 ${result.skuCode} 第${result.revision}版已发布；没有给学校新增授权`;await loadCatalog(1)}catch(e){error.value=e.message}finally{publishing.value=false}}
onBeforeRouteLeave(()=>!(attempt.value||rows.value.length)||window.confirm(attempt.value?'原订单结果尚未核对。离开后原请求仍保留在本标签页，请回到同一学校核对，不能重新建单。确认离开？':'离开将丢弃尚未提交的销售草稿，确认继续？'))
function beforeUnload(event){if(attempt.value||rows.value.length){event.preventDefault();event.returnValue=''}}
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);access.value=await ensurePlatformAccessContext({force:true});if(!access.value)error.value='平台职责核验失败，销售操作已关闭';loadPending();await Promise.all([loadSchools(1),loadCatalog(1),loadContext()])})
onBeforeUnmount(()=>{epoch++;schoolSeq++;catalogSeq++;contextSeq++;orderSeq++;detailSeq++;previewSeq++;window.removeEventListener('beforeunload',beforeUnload)})
</script>
