dff;border-radius:12px;padding:18px;margin-top:16px}.order-line header{display:flex;justify-content:space-between;align-items:center;gap:14px}.order-line h4{margin:0;font-size:15px}.line-fields{display:grid;grid-template-columns:repeat(4,minmax(100px,1fr));gap:14px;margin-top:14px}.line-fields label:nth-last-child(-n+2){grid-column:span 2}.line-net{display:grid;gap:7px;padding:6px 12px;background:#edf4ff;border-radius:8px}.line-net span{font-size:11px;color:#59718f}.line-net strong{font-size:19px}.coverage{background:#edf4ff;padding:8px 12px;border-radius:7px}.submit-bar{justify-content:space-between;align-items:center;padding:18px 0;font-size:12px;color:#657992}.quote,.detail{border:1px solid #bfd2ee;border-radius:12px;padding:20px;margin-top:16px;background:#f8fbff}.quote-total{font-size:30px;color:#174c94}.check{display:flex;align-items:center;gap:10px;margin:16px 0}.check input,.features input{min-height:auto}.notice,.success,.error,.pending,.empty{padding:12px 15px;border-radius:8px;font-size:13px;line-height:1.7}.notice,.pending{background:#fff7e8;color:#865e1c}.success{background:#edf9f2;color:#246546}.error{background:#fff0f0;color:#a93d3d}.empty{background:#f4f7fb;color:#697b94}.publish-grid{display:grid;grid-template-columns:repeat(2,minmax(160px,1fr));gap:14px}.features{display:flex;gap:14px;flex-wrap:wrap;margin:20px 0;border:1px solid #e0e7ef;padding:16px;border-radius:10px}.features label{display:flex;align-items:center;gap:6px}.features legend{font-size:12px;color:#4b6686}fieldset{border:0;margin:0;padding:0;min-width:0}.table-scroll{overflow:auto;border:1px solid #e0e7ef;border-radius:9px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:left;padding:12px;border-bottom:1px solid #e8edf4;vertical-align:top;white-space:nowrap}th{background:#f3f7fc;color:#58708f;font-weight:600}h4{font-size:16px;margin:12px 0}.export-bar{padding-top:16px}.export-bar small{flex-basis:100%}a{color:#245fb6}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid #2563eb;outline-offset:3px}@media(max-width:900px){.sales-workspace{padding:16px}.line-fields,.publish-grid{grid-template-columns:repeat(2,minmax(120px,1fr))}.school-select{min-width:220px}.catalog-grid{grid-template-columns:repeat(auto-fit,minmax(185px,1fr))}}@media(max-width:560px){.line-fields,.publish-grid{grid-template-columns:1fr}.line-fields label:nth-last-child(-n+2){grid-column:auto}.school-tools>label,.draft-head>label{width:100%;min-width:0}.sales-heading{align-items:start}}
